from pathlib import Path

PROJECT_ROOT = Path(__file__).resolve().parent
VERBOSE = True


class CleanupReport:
    def __init__(self):
        self.scanned = 0
        self.deleted = 0

    def note_scanned(self):
        self.scanned += 1

    def note_deleted(self):
        self.deleted += 1

    def render(self):
        return "scanned %d file(s), deleted %d file(s)" % (self.scanned, self.deleted)


def log(message):
    if VERBOSE:
        print("[cleanup] " + str(message))


def parse_args(argv):
    target = None
    confirmed = False
    for arg in argv:
