    if not confirmed:
        log("nothing deleted; re-run with --yes to actually delete")
        return 0

    for path in victims:
        os.remove(path)
        report.note_deleted()
        log("deleted " + str(path))

    log(report.render())
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv[1:]))
